(() => {
  const removeLimits = root => {
    if (root.nodeType !== 1) return;
    if (root.matches("input, textarea")) root.removeAttribute("maxlength");
    root.querySelectorAll?.("input, textarea").forEach(el => el.removeAttribute("maxlength"));
  };
  removeLimits(document.documentElement);
  const observer = new MutationObserver(records => {
    for (const record of records) {
      record.addedNodes.forEach(removeLimits);
      if (record.target.nodeType === 1) removeLimits(record.target);
    }
  });
  observer.observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ["maxlength"] });
})();
